for(const mode of['miss','blocked','control']){const s=make({move:10780,index:-1,soul:true,hit:mode!=='miss'});if(mode==='miss')timer(s,0,'攻击必失');if(mode==='blocked')timer(s,0,'skillBlock');if(mode==='control')s.fighters[0].ailments['害怕']=2;turn(s);assert.equal(s.fighters[0].soulState.phalanx2044?.hits??0,0);assert.equal(sum(s,'percent'),0);}
const a=make({move:10780,index:-1,soul:true,aStats:{def:300,spd:500}});turn(a,24585);assert.equal(a.fighters[0].soulState.phalanx2044?.hits??0,0);turn(a);assert.equal(sum(a,'percent'),150);
const b=make({move:10780,index:-1,soul:true,aStats:{def:300,spd:500}});timer(b,1,'攻击伤害免疫');timer(b,1,'固定百分比免疫');turn(b);assert.equal(sum(b),0);assert.equal(sum(b,'percent'),0);assert.equal(b.fighters[0].soulState.phalanx2044.hits,1);delete b.fighters[1].effects['固定百分比免疫'];turn(b);assert.equal(sum(b),0);assert.equal(sum(b,'percent'),250);

for(const m of source.moves)for(let index=0;index<m.effectInstances.length;index++){const e=m.effectInstances[index];if(![4,5].includes(e.id))continue;const a=make({move:m.id,index});turn(a);const side=e.id===4?0:1,k=keys[e.args[0]];assert.equal(a.fighters[side].stages[k],e.args[2]+(side===1&&k==='atk'?1:0));}
for(const r of[row(14),row(15),row(14,1),row(14,2)]){const instance=source.moves.find(m=>m.id===r.move).effectInstances[r.index],name=instance.id===14?'冻伤':'害怕',seen=new Set();for(let seed=1;seed<=(instance.args[0]===100?1:32);seed++){const a=make({...r,seed:Math.imul(seed,0x9e3779b1)>>>0});turn(a);seen.add(!!a.fighters[1].ailments[name]);const b=make({...r,seed:Math.imul(seed,0x9e3779b1)>>>0});b.fighters[1].counts.immune=1;turn(b);assert.equal(b.fighters[1].ailments[name],undefined);}assert.ok(seen.has(true));if(instance.args[0]<100)assert.ok(seen.has(false));}
const a=make(row(33));a.fighters[1].stages.def=2;turn(a);assert.equal(a.fighters[1].stages.def,0);const b=make(row(33));timer(b,1,'强化保护');b.fighters[1].stages.def=2;turn(b);assert.equal(b.fighters[1].stages.def,2);const c=make(row(29));turn(c);assert.equal(sum(c,'fixed'),150);

